from __future__ import annotations

import re
from pathlib import Path

from workpeg.starter import write_agent_guide, write_starter
from workpeg.ui.build import _derive_peg_namespace, build_ui


# The starter itself lives in workpeg/templates/starter/ and is written by
# workpeg.starter, so `workpeg ui new` and `workpeg project create` give an
# agent the same code to copy, and AGENTS.md describes the files both write.


class ProjectExistsError(Exception):
    pass


def to_class_name(name: str) -> str:
    """Convert any slug to a valid PascalCase Python identifier."""
    parts = re.split(r"[-_\s]+", name)
    class_name = "".join(p.capitalize() for p in parts if p)
    if not class_name:
        return "App"
    if not class_name[0].isalpha():
        class_name = "App" + class_name
    return class_name


def to_filename(name: str) -> str:
    """Convert any slug to a snake_case Python module name."""
    slug = re.sub(r"[-\s]+", "_", name.lower())
    slug = re.sub(r"[^a-z0-9_]", "", slug)
    return slug or "app"


def create_ui_project(
    name: str,
    directory: str = ".",
    *,
    force: bool = False,
) -> tuple[Path, Path]:
    """
    Scaffold a new Workpeg UI (Scaffold app-chrome) project, compile it, and
    return (project_dir, source_file).

    Project layout created::

        <name>/
        ├── AGENTS.md            ← the guide a coding agent reads first
        ├── CLAUDE.md            ← one line: @AGENTS.md
        ├── main.py              ← Router + Landing (source_file)
        ├── app_shell.py         ← AppShell(Shell) → the SDK Scaffold
        ├── components.py        ← PageHeader, Loading/Empty/ErrorState, ...
        ├── pages/
        │   ├── __init__.py
        │   ├── home.py          ← HomePage
        │   ├── customers.py     ← a list page over one table
        │   ├── customer.py      ← its detail page
        │   └── not_found.py     ← NotFoundPage (404)
        └── dist/                ← compiled output

    The app uses the SDK ``Scaffold``, so it renders behind an auth gate:
    run it signed in with ``workpeg ui serve <name> --fake-cloud``, which
    serves the release build at ``https://<namespace>.dev.workpeg.com``
    from this computer for a dev install (docs/dev-install.md), rather than
    a bare static serve.

    An ``AGENTS.md`` or ``CLAUDE.md`` already in the folder is kept, even
    with *force*.

    Raises ProjectExistsError if the project directory already exists
    and force is False.
    """
    project_dir = Path(directory) / name

    if project_dir.exists() and not force:
        raise ProjectExistsError(
            f"'{project_dir}' already exists. Use --force to overwrite."
        )

    project_dir.mkdir(parents=True, exist_ok=True)
    source_file = project_dir / "main.py"

    # The name a build of this folder will carry, so the guide's commands
    # and the page agree on it.
    namespace = _derive_peg_namespace(str(source_file))
    write_starter(project_dir, namespace, force=True)
    write_agent_guide(project_dir, namespace)

    build_ui(str(source_file), str(project_dir / "dist"))

    return project_dir, source_file
